/****** Object:  StoredProcedure [dbo].[GuardarRepuestoApp]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Adapta el mantenimiento de Jean Carlo sin modificar sus scripts.
CREATE   PROCEDURE [dbo].[GuardarRepuestoApp]
    @IdCategoria INT,
    @Codigo VARCHAR(30) = NULL,
    @Nombre NVARCHAR(120),
    @PrecioVenta DECIMAL(10,2),
    @Costo DECIMAL(10,2),
    @Activo BIT,
    @IdRepuesto INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF NULLIF(LTRIM(RTRIM(@Nombre)), '') IS NULL
        THROW 50003, 'El nombre es obligatorio.', 1;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @IdRepuesto IS NULL
        BEGIN
            DECLARE @Numero BIGINT;
            -- La secuencia asigna numeros distintos incluso entre sesiones simultaneas.
            -- Se omiten codigos que hayan sido cargados previamente por otra via.
            WHILE 1 = 1
            BEGIN
                SET @Numero = NEXT VALUE FOR dbo.SecuenciaCodigoRepuesto;
                SET @Codigo = 'REP-' + CASE WHEN @Numero < 1000000
                    THEN RIGHT('000000' + CONVERT(VARCHAR(20), @Numero), 6)
                    ELSE CONVERT(VARCHAR(20), @Numero) END;
                IF NOT EXISTS (SELECT 1 FROM dbo.Repuesto WHERE Codigo = @Codigo) BREAK;
            END;
            EXEC dbo.MantenimientoRepuesto @function = 1, @IdCategoria = @IdCategoria,
                @Codigo = @Codigo, @Nombre = @Nombre, @PrecioVenta = @PrecioVenta, @Costo = @Costo, @Activo = @Activo;
            -- El codigo es unico; se recupera dentro de la misma transaccion.
            SELECT @IdRepuesto = IdRepuesto FROM dbo.Repuesto WHERE Codigo = @Codigo;
        END
        ELSE
        BEGIN
            SET @Codigo = NULL;
            SELECT @Codigo = Codigo FROM dbo.Repuesto WITH (UPDLOCK, HOLDLOCK) WHERE IdRepuesto = @IdRepuesto;
            IF @Codigo IS NULL
                THROW 50004, 'El repuesto no existe.', 1;
            EXEC dbo.MantenimientoRepuesto @function = 2, @IdRepuesto = @IdRepuesto,
                @IdCategoria = @IdCategoria, @Codigo = @Codigo, @Nombre = @Nombre,
                @PrecioVenta = @PrecioVenta, @Costo = @Costo, @Activo = @Activo;
        END;
        COMMIT TRANSACTION;
        SELECT @IdRepuesto AS IdRepuesto;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

GO
/****** Object:  StoredProcedure [dbo].[LoginUsuario]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Instalar despues del ensamblado CLR y dbo.VerificarClave.
CREATE   PROCEDURE [dbo].[LoginUsuario]
    @Correo VARCHAR(100),
    @Clave NVARCHAR(256),
    @Valido BIT = NULL OUTPUT,
    @HashVerificado VARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET @Valido = 0;
    DECLARE @Hash VARCHAR(255), @IdUsuario INT;
    SELECT @IdUsuario = u.IdUsuario, @Hash = u.Contrasena
    FROM dbo.Usuario u JOIN dbo.Rol r ON r.IdRol = u.IdRol
    WHERE u.Correo = @Correo AND u.Activo = 1
      AND ((r.Nombre IN ('Administrador', 'Empleado')
            AND (SELECT COUNT(*) FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario) = 1
            AND NOT EXISTS (SELECT 1 FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario))
        OR (r.Nombre = 'Cliente'
            AND (SELECT COUNT(*) FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario) = 1
            AND NOT EXISTS (SELECT 1 FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario)));
    IF @IdUsuario IS NOT NULL AND dbo.VerificarClave(@Clave, @Hash) = 1
    BEGIN
        -- Releer despues de PBKDF2 para detectar cambios concurrentes de cuenta o clave.
        SELECT u.IdUsuario, u.Correo, CAST(NULL AS VARCHAR(255)) AS HashContrasena,
            r.Nombre AS Rol, e.IdEmpleado, a.IdAseguradora,
            COALESCE(e.Nombre, a.Nombre, u.Correo) AS Nombre
        FROM dbo.Usuario u JOIN dbo.Rol r ON r.IdRol = u.IdRol
        LEFT JOIN dbo.Empleado e ON e.IdUsuario = u.IdUsuario
        LEFT JOIN dbo.Aseguradora a ON a.IdUsuario = u.IdUsuario
        WHERE u.IdUsuario = @IdUsuario AND u.Activo = 1
          AND CONVERT(VARBINARY(255),u.Contrasena) = CONVERT(VARBINARY(255),@Hash)
          AND (@HashVerificado IS NULL OR CONVERT(VARBINARY(255),@HashVerificado) = CONVERT(VARBINARY(255),@Hash))
          AND ((r.Nombre IN ('Administrador', 'Empleado')
                AND (SELECT COUNT(*) FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario) = 1
                AND NOT EXISTS (SELECT 1 FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario))
            OR (r.Nombre = 'Cliente'
                AND (SELECT COUNT(*) FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario) = 1
                AND NOT EXISTS (SELECT 1 FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario)));
        IF @@ROWCOUNT = 1 SET @Valido = 1;
    END;
END;

GO
