/****** Object:  StoredProcedure [dbo].[ObtenerCredencialLogin]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[ObtenerCredencialLogin]
    @Correo VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    -- Una cuenta debe tener un unico perfil coherente antes de permitir el acceso.
    SELECT u.IdUsuario, u.Correo, u.Contrasena AS HashContrasena, r.Nombre AS Rol,
           e.IdEmpleado, a.IdAseguradora, COALESCE(e.Nombre, a.Nombre, u.Correo) AS Nombre
    FROM dbo.Usuario u
    JOIN dbo.Rol r ON r.IdRol = u.IdRol
    LEFT JOIN dbo.Empleado e ON e.IdUsuario = u.IdUsuario
    LEFT JOIN dbo.Aseguradora a ON a.IdUsuario = u.IdUsuario
    WHERE u.Correo = @Correo AND u.Activo = 1
      AND ((r.Nombre IN ('Administrador', 'Empleado')
            AND (SELECT COUNT(*) FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario) = 1
            AND NOT EXISTS (SELECT 1 FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario))
        OR (r.Nombre = 'Cliente'
            AND (SELECT COUNT(*) FROM dbo.Aseguradora WHERE IdUsuario = u.IdUsuario) = 1
            AND NOT EXISTS (SELECT 1 FROM dbo.Empleado WHERE IdUsuario = u.IdUsuario)));
END;

GO
/****** Object:  Trigger [dbo].[TR_Aseguradora_ValidarRol]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--Aseguradora
CREATE   TRIGGER [dbo].[TR_Aseguradora_ValidarRol]
on [dbo].[Aseguradora]
after insert, update
as
begin
    set nocount on

    if exists (
        select 1
        from inserted i
        join Usuario u on u.IdUsuario = i.IdUsuario
        join Rol r     on r.IdRol     = u.IdRol
        where r.Nombre <> 'Cliente'
    )
    begin
        raiserror('Error, el usuario asignado a la aseguradora debe tener rol Cliente',16,1)
        rollback transaction
        return
    end
end
GO
ALTER TABLE [dbo].[Aseguradora] ENABLE TRIGGER [TR_Aseguradora_ValidarRol]
GO
/****** Object:  Trigger [dbo].[TR_Compra_ValidarBodega]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Un detalle recibido pertenece a una bodega: no mover la cabecera sin su stock.
CREATE   TRIGGER [dbo].[TR_Compra_ValidarBodega]
ON [dbo].[Compra] AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM inserted i JOIN deleted d ON d.IdCompra = i.IdCompra
        WHERE i.IdBodega <> d.IdBodega
          AND EXISTS (SELECT 1 FROM dbo.DetalleCompra dc WHERE dc.IdCompra = i.IdCompra))
        THROW 50043, 'Una compra con detalles no puede cambiar de bodega; utilice un traslado.', 1;
END;

GO
ALTER TABLE [dbo].[Compra] ENABLE TRIGGER [TR_Compra_ValidarBodega]
GO
/****** Object:  Trigger [dbo].[TR_DetalleCompra_Inventario]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--INVENTARIO
   

--Compras: suman existencias en la bodega de la compra
CREATE   TRIGGER [dbo].[TR_DetalleCompra_Inventario]
on [dbo].[DetalleCompra]
after insert, update, delete
as
begin
    set nocount on

    declare @Cambios table (IdBodega int, IdRepuesto int, Cantidad int)

    insert into @Cambios (IdBodega, IdRepuesto, Cantidad)
    select x.IdBodega, x.IdRepuesto, sum(x.Cantidad)
    from (
        select c.IdBodega, i.IdRepuesto, i.Cantidad          -- lo nuevo suma
        from inserted i
        join Compra c on c.IdCompra = i.IdCompra
        union all
        select c.IdBodega, d.IdRepuesto, -d.Cantidad         -- lo anterior se revierte
        from deleted d
        join Compra c on c.IdCompra = d.IdCompra
    ) x
    group by x.IdBodega, x.IdRepuesto
    having sum(x.Cantidad) <> 0

    -- validar que ninguna existencia quede negativa
    if exists (
        select 1
        from @Cambios ca
        left join Inventario inv on inv.IdBodega = ca.IdBodega and inv.IdRepuesto = ca.IdRepuesto
        where isnull(inv.Cantidad, 0) + ca.Cantidad < 0
    )
    begin
        raiserror('Error, la operacion deja existencias negativas en inventario',16,1)
        rollback transaction
        return
    end

    -- actualizar existencias que ya existen
    update inv
    set inv.Cantidad = inv.Cantidad + ca.Cantidad
    from Inventario inv
    join @Cambios ca on ca.IdBodega = inv.IdBodega and ca.IdRepuesto = inv.IdRepuesto

    -- crear la fila si el repuesto no existia en esa bodega
    insert into Inventario (IdBodega, IdRepuesto, Cantidad)
    select ca.IdBodega, ca.IdRepuesto, ca.Cantidad
    from @Cambios ca
    where not exists (select 1 from Inventario inv
                      where inv.IdBodega = ca.IdBodega and inv.IdRepuesto = ca.IdRepuesto)
end
GO
ALTER TABLE [dbo].[DetalleCompra] ENABLE TRIGGER [TR_DetalleCompra_Inventario]
GO
/****** Object:  Trigger [dbo].[TR_DetalleCompra_Total]    Script Date: 13/10/2026 11:56:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--TOTALES
  

--Compra.Total = suma(Cantidad * Costo)
CREATE   TRIGGER [dbo].[TR_DetalleCompra_Total]
on [dbo].[DetalleCompra]
after insert, update, delete
as
begin
    set nocount on

    update c
    set c.Total = isnull((select sum(dc.Cantidad * dc.Costo)
                          from DetalleCompra dc
                          where dc.IdCompra = c.IdCompra), 0)
    from Compra c
    where c.IdCompra in (select IdCompra from inserted
                         union
                         select IdCompra from deleted)
end
GO
ALTER TABLE [dbo].[DetalleCompra] ENABLE TRIGGER [TR_DetalleCompra_Total]
GO
/****** Object:  Trigger [dbo].[TR_DetalleCotizacion_Total]    Script Date: 13/10/2026 11:56:21 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--Cotizacion.Total = suma(Cantidad * Precio)
CREATE   TRIGGER [dbo].[TR_DetalleCotizacion_Total]
on [dbo].[DetalleCotizacion]
after insert, update, delete
as
begin
    set nocount on

    update co
    set co.Total = isnull((select sum(dc.Cantidad * dc.Precio)
                           from DetalleCotizacion dc
                           where dc.IdCotizacion = co.IdCotizacion), 0)
    from Cotizacion co
    where co.IdCotizacion in (select IdCotizacion from inserted
                              union
                              select IdCotizacion from deleted)
end
GO
ALTER TABLE [dbo].[DetalleCotizacion] ENABLE TRIGGER [TR_DetalleCotizacion_Total]
