/****** Object:  Trigger [dbo].[TR_Empleado_ValidarRol]    Script Date: 13/10/2026 11:56:21 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--VALIDACION DE ROL
 --Empleado    -> el usuario debe tener rol 'Administrador' o 'Empleado'
 --Aseguradora -> el usuario debe tener rol 'Cliente'
  

--Empleado
CREATE   TRIGGER [dbo].[TR_Empleado_ValidarRol]
on [dbo].[Empleado]
after insert, update
as
begin
    set nocount on

    if exists (
        select 1
        from inserted i
        join Usuario u on u.IdUsuario = i.IdUsuario
        join Rol r     on r.IdRol     = u.IdRol
        where r.Nombre not in ('Administrador', 'Empleado')
    )
    begin
        raiserror('Error, el usuario asignado al empleado debe tener rol Administrador o Empleado',16,1)
        rollback transaction
        return
    end
end
GO
ALTER TABLE [dbo].[Empleado] ENABLE TRIGGER [TR_Empleado_ValidarRol]
GO
